# Approximate list prices in US$ per 1 million tokens (input, output). Check the provider's pricing page before quoting a client.
PRICES = {
    "bedrock": (0.035, 0.14),     # Amazon Nova Micro (on-demand, us-east-1)
    "azure": (0.25, 2.00),        # gpt-5.4-mini class (approx.); check your Azure pricing
    "openai": (0.25, 2.00),       # gpt-5-mini class
    "offline": (0.035, 0.14),     # pretend Nova Micro prices so the cost charts still mean something
}
LABELS = {"bedrock": "AWS Bedrock", "azure": "Azure AI Foundry", "openai": "OpenAI", "offline": "Offline stand-in"}


# ------------------------------------------------------------------------------------------------ which providers are ready
def status():
    """{provider: (ready, reason)} for the sidebar."""
    out = {}
    try:
        import boto3
        model = os.getenv("BEDROCK_SMALL_MODEL_ID", "")
        if not model or model == "REPLACE_ME":
            out["bedrock"] = (False, "BEDROCK_SMALL_MODEL_ID missing in .env")
        elif boto3.Session().get_credentials() is None:
            out["bedrock"] = (False, "AWS keys missing in .env")
        else:
            out["bedrock"] = (True, model)
    except Exception as e:
        out["bedrock"] = (False, f"boto3 problem: {e}")
    az_ok = bool(os.getenv("AZURE_OPENAI_API_KEY") and os.getenv("AZURE_OPENAI_ENDPOINT", "").startswith("http")
                 and "<" not in os.getenv("AZURE_OPENAI_ENDPOINT", "") and _azure_deployment())
    out["azure"] = (az_ok, _azure_deployment() if az_ok else "Azure keys not set in .env")
    out["openai"] = (bool(os.getenv("OPENAI_API_KEY")), os.getenv("OPENAI_MODEL", "gpt-5-mini") if os.getenv("OPENAI_API_KEY") else "OPENAI_API_KEY not set")
    out["offline"] = (True, "rule-based stand-in, no AI")
    return out


def auto_provider():
    forced = os.getenv("ASKIT_MODEL", "").strip().lower()
    if forced in LABELS:
        return forced
    st = status()
    return next(p for p in ("bedrock", "azure", "openai", "offline") if st[p][0])


AZURE_DEFAULT = "gpt-5.4-mini-1"          # the course-wide Azure chat deployment


def _azure_deployment():
    """Always gpt-5.4-mini-1, unless AZURE_OPENAI_CHAT_DEPLOYMENT (single name) is set in .env to override it."""
    return os.getenv("AZURE_OPENAI_CHAT_DEPLOYMENT", "").strip() or AZURE_DEFAULT


def get_model(provider=None):
    """Return a LangChain chat model for the provider (None = Auto)."""
    name = provider or auto_provider()
    if name == "bedrock":
        from botocore.config import Config
        from langchain_aws import ChatBedrockConverse
        return ChatBedrockConverse(model=os.getenv("BEDROCK_SMALL_MODEL_ID"), region_name=os.getenv("AWS_REGION", "us-east-1"),
                                   temperature=0, max_tokens=700,
                                   config=Config(retries={"max_attempts": 8, "mode": "adaptive"}, read_timeout=120))
    if name == "azure":
        from langchain_openai import ChatOpenAI
        u = urlparse(os.getenv("AZURE_OPENAI_ENDPOINT").strip())
        key = os.getenv("AZURE_OPENAI_API_KEY")
        return ChatOpenAI(model=_azure_deployment(), base_url=f"{u.scheme}://{u.netloc}/openai/v1", api_key=key,
                          default_headers={"api-key": key}, max_retries=4)
    if name == "openai":
        from langchain_openai import ChatOpenAI
        return ChatOpenAI(model=os.getenv("OPENAI_MODEL", "gpt-5-mini"), max_retries=4)
    return OfflineChatModel()


def model_label(provider):
    return f"{LABELS[provider]} · {status()[provider][1]}"


def cost_usd(provider, tokens_in, tokens_out):
    p_in, p_out = PRICES.get(provider, PRICES["bedrock"])
    return tokens_in / 1e6 * p_in + tokens_out / 1e6 * p_out


def text_of(message):
    """Plain text of a LangChain message (content can be a string or a list of blocks)."""
    c = getattr(message, "content", message)
    if isinstance(c, str):
        return c
    return "".join(b.get("text", "") for b in c if isinstance(b, dict))


def approx_tokens(text):
    return max(1, len(text) // 4)


# ------------------------------------------------------------------------------------------------ offline stand-in
STOP = set("the and for with that this you your are was has have not can how what which when where from into about please "
           "need want would could should does did its our any all one two get got let new use used using".split())


def _words(text):
    ws = {w for w in re.findall(r"[a-z0-9]+", str(text).lower())
          if len(w) > 2 and w not in STOP and not w.isdigit() and w not in ("tkt", "emp")}     # ids are not "words"
    return {w[:-1] if len(w) > 3 and w.endswith("s") else w for w in ws}      # passwords -> password


class OfflineChatModel(BaseChatModel):
    """NOT a real model: a few rules that behave like one, so the lab runs with no keys.
    To choose a tool it counts the words the question shares with each tool's NAME + DESCRIPTION.
    That is a crude version of what a real model does, and it shows why good descriptions matter."""

    tool_info: dict = {}        # tool name -> description

    @property
    def _llm_type(self):
        return "askit-offline"

    def bind_tools(self, tools, **kwargs):
        info = {}
        for t in tools:
            name = getattr(t, "name", None) or (t.get("name") if isinstance(t, dict) else None) or getattr(t, "__name__", "tool")
            desc = getattr(t, "description", None) or (t.get("description") if isinstance(t, dict) else "") or ""
            info[name] = desc
        return OfflineChatModel(tool_info=info)

    def _generate(self, messages, stop=None, run_manager=None, **kwargs):
        reply = self._reply(messages)
        n_in = sum(approx_tokens(text_of(m)) for m in messages)
        n_out = approx_tokens(text_of(reply) or "tool call")
        reply.usage_metadata = {"input_tokens": n_in, "output_tokens": n_out, "total_tokens": n_in + n_out}
        time.sleep(0.1)
        return ChatResult(generations=[ChatGeneration(message=reply)])

    # ------------------------------------------------------------------------------------------ the rules
    def _reply(self, messages):
        last = messages[-1]
        first = text_of(messages[0])
        if "ONE word" in first and "Network" in first:
            return AIMessage(content=_offline_route(text_of(last)))
        if isinstance(last, ToolMessage):
            return AIMessage(content=_summary(last.name, _as_dict(last.content)))
        human = [m for m in messages if isinstance(m, HumanMessage)]
        q = text_of(human[-1]) if human else ""
        pick = self._pick(q)
        if pick is None:
            return AIMessage(content="(offline) I am not sure which tool can help with that, so I will not call any.")
        return AIMessage(content="", tool_calls=[{"name": pick, "args": _args_for(pick, q), "id": f"off{len(messages)}",
                                                   "type": "tool_call"}])

    def _pick(self, q):
        qw = _words(q)
        best, best_score = None, 0
        for name, desc in self.tool_info.items():
            score = len(qw & (_words(desc) | _words(name.replace("_", " "))))
            if re.search(r"TKT-\d+", q, re.I) and "ticket" in (desc + name).lower():
                score += 1
            if re.search(r"EMP-\d+", q, re.I) and ("employee" in desc.lower() or "password" in (desc + name).lower()):
                score += 1
            if re.match(r"\s*(how|what|where|why|which|who)\b", q, re.I) and not re.search(r"(TKT|EMP)-\d+", q, re.I) \
                    and ("how-to" in desc.lower() or "knowledge base" in desc.lower()):
                score += 1                                      # an information question: a "how-to / knowledge base" tool fits
            if score > best_score:
                best, best_score = name, score
        return best


def _args_for(tool, q):
    """Fill the tool's inputs from the question (the real model does this by reading the tool's input schema)."""
    ticket = re.search(r"TKT-\d+", q, re.I)
    user = re.search(r"EMP-\d+", q, re.I)
    if tool == "get_ticket":
        return {"ticket_id": ticket.group(0).upper() if ticket else "TKT-0001"}
    if tool == "update_ticket":
        return {"ticket_id": ticket.group(0).upper() if ticket else "TKT-0001", "note": q.split(":", 1)[-1].strip()[:200]}
    if tool == "reset_password":
        return {"user_id": user.group(0).upper() if user else "EMP-1021"}
    return {"query": q[:120]}


def _as_dict(content):
    try:
        data = json.loads(content) if isinstance(content, str) else content
        return data if isinstance(data, dict) else {"result": data}
    except Exception:
        return {"result": str(content)}


def _summary(tool_name, data):
    if "error" in data:
        return "Sorry, that did not work: " + str(data["error"])
    if data.get("results"):
        top = data["results"][0]
        return f"Best match [{top['id']}]: " + " ".join(top["text"].split())[:220]
    if "subject" in data:
        return f"Ticket {data['ticket_id']} ({data['subject']}) is {data['status']}, priority {data['priority']}."
    if data.get("ok"):
        return data.get("message") or "Done."
    if data.get("message"):
        return str(data["message"])
    return "I could not find anything useful for that."


ROUTE_WORDS = {
    "Access": ["password", "locked", "login", "access", "mfa", "admin", "account", "permission"],
    "Network": ["vpn", "wifi", "wi-fi", "network", "internet", "connect", "809"],
    "Hardware": ["laptop", "screen", "monitor", "battery", "keyboard", "printer", "blue screen", "device", "phone"],
}


def _offline_route(text):
    tl = text.lower()
    scores = {r: sum(w in tl for w in words) for r, words in ROUTE_WORDS.items()}
    best = max(scores, key=scores.get)
    return best if scores[best] else "General"
